import {mountRealData} from './real-crop-data.js';
import {crops} from './crop-catalog.js';
import {mountAssessment} from './field-assessment.js';
import {decisionEvidence} from './decision-evidence.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountRotationStage(host,farm,context={}){let selected=crops.find(c=>farm.crop?.startsWith(c.name))||crops[4],step=0;const labels=['1 · Mis datos','2 · Mis alternativas','3 · Mi siguiente paso'];
host.innerHTML='<section class="rotation-theatre rotation-immersive" role="dialog" aria-modal="true" aria-label="Explorar alternativas de cultivo"><div class="rotation-launch"><button id="crop-close">Salir de la experiencia ✕</button></div><div class="rotation-heading"><small>EL FUTURO DE TU FINCA</small><h2>¿Qué puedo hacer<br>con mi finca?</h2><p>Primero revisa tus datos. Después compara mantener tu cultivo, cambiar a otro frutal o planificar arroz en un lote anual.</p><div class="notice">Aún no hay rotaciones validadas para esta finca. Las opciones son propuestas para evaluar, no instrucciones de siembra.</div></div><nav class="crop-journey" aria-label="Tu recorrido"></nav><div id="crop-data-status"></div><div id="real-crop-data"></div><div class="rotation-paths"></div><div class="rotation-scene"></div><div class="rotation-story" aria-live="polite"></div><nav class="rotation-timeline" aria-label="Pasos de evaluación"></nav><div class="rotation-actions"><button id="crop-prev">← Anterior</button><button id="crop-next">Siguiente →</button></div><div id="crop-evidence"></div><div id="crop-assessment"></div><button id="crop-compare">Comparar las seis alternativas</button><div id="crop-comparison" hidden></div></section>';
const root=host.firstElementChild,old=document.body.style.overflow;document.body.style.overflow='hidden';function close(){root.classList.remove('rotation-immersive');root.removeAttribute('aria-modal');document.body.style.overflow=old;}host.querySelector('#crop-close').onclick=close;root.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&root.classList.contains('rotation-immersive')){const nodes=[...root.querySelectorAll('button,input,select,textarea,summary,a[href]')].filter(n=>!n.disabled&&n.getClientRects().length);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus()}}});
mountRealData(host.querySelector('#real-crop-data'),context);
mountAssessment(host.querySelector('#crop-assessment'),farm,context);
function draw(){
const real=context.source?.startsWith('NASA POWER'),valid=(context.rows||[]).filter(r=>Number.isFinite(r.temp));
host.querySelector('#crop-data-status').innerHTML='<h3>¿Qué sabemos de tu finca?</h3><p><strong>Terreno:</strong> '+(context.area?'Tienes una figura delimitada.':'Estás explorando sin una figura confirmada.')+'</p><p><strong>Clima:</strong> '+(real&&valid.length?'Histórico NASA cargado: '+valid.length+' días con temperatura.':'Sin histórico NASA cargado; no usamos la demostración como evidencia real.')+'</p>'+(real&&valid.length?'<p>Periodo: '+esc(valid[0].date)+' a '+esc(valid.at(-1).date)+'. Fuente: '+esc(context.source)+'.</p>':'')+'<p>La consulta climática representa un punto de referencia, no todas las partes del polígono. No es un pronóstico actual.</p><p><strong>Por confirmar:</strong> cultivo real, suelo, agua de riego, costos y aptitud de cada alternativa.</p>';
host.querySelector('#crop-data-status').hidden=step!==0;host.querySelector('.rotation-paths').hidden=step!==1;host.querySelector('.rotation-scene').hidden=step===0;host.querySelector('#crop-evidence').hidden=step!==0;host.querySelector('#crop-assessment').hidden=step!==0;host.querySelector('#crop-compare').hidden=step!==1;host.querySelector('#crop-comparison').hidden=true;
host.querySelector('.crop-journey').innerHTML=labels.map((label,i)=>'<button data-journey="'+i+'" '+(step===i?'aria-current="step"':'')+'>'+label+'</button>').join('');host.querySelectorAll('[data-journey]').forEach(el=>el.onclick=()=>{step=Number(el.dataset.journey);draw()});
host.querySelector('.rotation-paths').innerHTML=crops.map((c,i)=>'<button data-crop="'+i+'" aria-pressed="'+(c.name===selected.name)+'"><span>'+c.symbol+'</span>'+c.name+'<small>'+(farm.crop?.startsWith(c.name)?'Mantener y adaptar':c.name==='Arroz'?'Campaña en lote anual':'Cambio a largo plazo')+'</small><small>Por evaluar · sin validación</small></button>').join('');host.querySelectorAll('[data-crop]').forEach(el=>el.onclick=()=>{selected=crops[Number(el.dataset.crop)];step=1;draw()});
host.querySelector('.rotation-scene').innerHTML='<svg viewBox="0 0 800 350" role="img" aria-label="Ilustración conceptual de '+selected.name+'; no es una predicción"><ellipse cx="400" cy="300" rx="300" ry="30" fill="#061f1944"/><path d="M80 160 400 45 720 160 400 310Z" fill="#a9c878"/><path d="M80 160v30l320 150v-30Zm320 150v30l320-150v-30Z" fill="#96734f"/>'+Array.from({length:12},(_,i)=>'<g transform="translate('+(200+i%4*85+Math.floor(i/4)*30)+' '+(145-i%4*15+Math.floor(i/4)*40)+')"><text class="rotation-stem" font-size="'+(step===0?25:48)+'" text-anchor="middle">'+(step===0?'🌱':selected.symbol)+'</text></g>').join('')+'</svg>';
const text=step===0?'Completa los datos de campo que faltan o continúa para conocer las alternativas. Ninguna está validada todavía.':step===1?selected.action:'Has elegido explorar '+selected.name+'. Siguiente paso: confirmar agua de riego y análisis de suelo, y revisar con un técnico su viabilidad, inversión y mercado. Esta elección no autoriza sembrar ni sustituir tus árboles.';host.querySelector('.rotation-story').innerHTML='<small>PASO '+(step+1)+' / 3 · '+selected.type+'</small><h3>'+selected.symbol+' '+selected.name+'</h3><p>'+text+'</p>';
host.querySelector('.rotation-timeline').innerHTML=labels.map((label,i)=>'<button data-step="'+i+'" '+(i===step?'aria-current="step"':'')+'>'+label+'</button>').join('');host.querySelectorAll('[data-step]').forEach(el=>el.onclick=()=>{step=Number(el.dataset.step);draw()});host.querySelector('#crop-prev').disabled=step===0;host.querySelector('#crop-next').textContent=step===2?'Volver a las alternativas':step===0?'Ver mis alternativas →':'Revisar mi elección →';host.querySelector('#crop-evidence').innerHTML='<details><summary>Ver datos del cultivo actual: '+esc(farm.crop)+'</summary>'+decisionEvidence(farm,context).notes.map(n=>'<p>'+esc(n)+'</p>').join('')+'</details>';}
host.querySelector('#crop-prev').onclick=()=>{step=Math.max(0,step-1);draw()};host.querySelector('#crop-next').onclick=()=>{if(step===2){step=1;draw()}else{step++;draw()}};host.querySelector('#crop-compare').onclick=()=>{const panel=host.querySelector('#crop-comparison');panel.hidden=false;panel.innerHTML='<h3>Alternativas propuestas, pendientes de evaluación</h3><div class="rotation-compare-grid">'+crops.map(c=>'<article><h4>'+c.symbol+' '+c.name+'</h4><strong>'+c.type+'</strong><p>'+c.action+'</p><p>Agua, tiempo hasta cosecha, costos y aptitud: sin determinar.</p></article>').join('')+'</div>';panel.scrollIntoView({block:'start'});};draw();host.querySelector('#crop-close').focus();}
